CREATE TABLE IF NOT EXISTS cam.wheelseye_sources (id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES cam.tenants(id) ON DELETE CASCADE,label text NOT NULL CHECK(length(label) BETWEEN 1 AND 100),endpoint_url text NOT NULL CHECK(endpoint_url='https://api.wheelseye.com/currentLoc'),payload bytea NOT NULL,device_cache jsonb NOT NULL DEFAULT '[]',enabled boolean NOT NULL DEFAULT true,poll_interval_seconds integer NOT NULL DEFAULT 60 CHECK(poll_interval_seconds BETWEEN 60 AND 3600),last_polled_at timestamptz,last_success_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,endpoint_url,label));
CREATE TABLE IF NOT EXISTS cam.wheelseye_devices (tenant_id uuid NOT NULL REFERENCES cam.tenants(id) ON DELETE CASCADE,source_id uuid NOT NULL REFERENCES cam.wheelseye_sources(id) ON DELETE CASCADE,device_number text NOT NULL,vehicle_number text NOT NULL DEFAULT '',vendor_code text,vendor_name text,provider text NOT NULL DEFAULT 'WHEELSEYE',vehicle_type text,data jsonb NOT NULL DEFAULT '{}',first_seen_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,source_id,device_number));
CREATE TABLE IF NOT EXISTS cam.wheelseye_location_logs (tenant_id uuid NOT NULL REFERENCES cam.tenants(id) ON DELETE CASCADE,source_id uuid NOT NULL REFERENCES cam.wheelseye_sources(id) ON DELETE CASCADE,device_number text NOT NULL,gps_time bigint NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),latitude double precision NOT NULL,longitude double precision NOT NULL,speed double precision NOT NULL DEFAULT 0,ignition boolean NOT NULL DEFAULT false,angle double precision NOT NULL DEFAULT 0,charge_on boolean,accurate boolean,payload jsonb NOT NULL,PRIMARY KEY(tenant_id,source_id,device_number,gps_time));
CREATE INDEX IF NOT EXISTS wheelseye_logs_device_time ON cam.wheelseye_location_logs(tenant_id,device_number,gps_time DESC);
ALTER TABLE cam.wheelseye_sources ENABLE ROW LEVEL SECURITY; ALTER TABLE cam.wheelseye_devices ENABLE ROW LEVEL SECURITY; ALTER TABLE cam.wheelseye_location_logs ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS wheelseye_sources_admin ON cam.wheelseye_sources; DROP POLICY IF EXISTS wheelseye_devices_read ON cam.wheelseye_devices; DROP POLICY IF EXISTS wheelseye_logs_read ON cam.wheelseye_location_logs;
CREATE POLICY wheelseye_sources_admin ON cam.wheelseye_sources FOR ALL USING(tenant_id=cam.workspace() AND cam.actor_role()='admin') WITH CHECK(tenant_id=cam.workspace() AND cam.actor_role()='admin'); CREATE POLICY wheelseye_devices_read ON cam.wheelseye_devices FOR SELECT USING(tenant_id=cam.workspace() AND cam.actor_role() IN ('admin','member')); CREATE POLICY wheelseye_logs_read ON cam.wheelseye_location_logs FOR SELECT USING(tenant_id=cam.workspace() AND cam.actor_role() IN ('admin','member')); CREATE POLICY wheelseye_devices_write ON cam.wheelseye_devices FOR ALL USING(tenant_id=cam.workspace() AND cam.actor_role()='admin') WITH CHECK(tenant_id=cam.workspace() AND cam.actor_role()='admin'); CREATE POLICY wheelseye_logs_write ON cam.wheelseye_location_logs FOR INSERT WITH CHECK(tenant_id=cam.workspace() AND cam.actor_role()='admin');
GRANT SELECT,INSERT,UPDATE,DELETE ON cam.wheelseye_sources,cam.wheelseye_devices,cam.wheelseye_location_logs TO cam_app;
CREATE OR REPLACE FUNCTION cam.wheelseye_candidates() RETURNS TABLE(id uuid,tenant_id uuid,payload bytea,poll_interval_seconds integer) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,cam AS $$ SELECT s.id,s.tenant_id,s.payload,s.poll_interval_seconds FROM cam.wheelseye_sources s JOIN cam.tenants t ON t.id=s.tenant_id WHERE s.enabled AND t.status='active' AND (s.last_polled_at IS NULL OR s.last_polled_at <= now() - make_interval(secs => s.poll_interval_seconds)) ORDER BY s.last_polled_at NULLS FIRST,s.id LIMIT 500 $$;
CREATE OR REPLACE FUNCTION cam.wheelseye_mark(source_id uuid, ok boolean, error_text text DEFAULT NULL) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,cam AS $$ UPDATE cam.wheelseye_sources SET last_polled_at=now(),last_success_at=CASE WHEN ok THEN now() ELSE last_success_at END,last_error=CASE WHEN ok THEN NULL ELSE left(coalesce(error_text,'poll failed'),500) END,updated_at=now() WHERE id=source_id $$;
GRANT EXECUTE ON FUNCTION cam.wheelseye_candidates(),cam.wheelseye_mark(uuid,boolean,text) TO cam_app;
